(() => {
  const $ = id => document.getElementById(id); let ws, state, catalogue = [], focus = null, tab = 'sensors', catIndex = 0, renderedTab = null, renderedCat = -1, renderedCatLen = 0, mySession = sessionStorage.bridgeSession || null, prepWeapon = '', prepShot = '';
  const params = new URLSearchParams(location.search); const channelId = params.get('channelId') || 'bridge'; const instanceId = params.get('instanceId') || 'default';
  const send = m => ws?.readyState === WebSocket.OPEN && ws.send(JSON.stringify(m));
  const esc = s => String(s ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
  function connect(){ ws = new WebSocket(`${location.protocol === 'https:' ? 'wss':'ws'}://${location.host}/ws`); ws.onopen=()=>send({type:'hello',hello:{channelId,instanceId,userId:params.get('userId')||'browser',name:params.get('name')||'Bridge crew',sessionId:sessionStorage.bridgeSession||null}}); ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='hello'&&m.clientId){sessionStorage.bridgeSession=m.clientId;mySession=m.clientId;}if(m.state){state=m.state;catalogue=m.catalogue||catalogue; render()} }; ws.onclose=()=>{$('status').textContent='OFFLINE';setTimeout(connect,2000)} }
  function focusInContent(){ const a=document.activeElement; return !!(a&&a.tagName&&/^(SELECT|INPUT|TEXTAREA)$/.test(a.tagName)&&a.closest&&a.closest('#content')); } function render(){ $('status').textContent=state?state.status.toUpperCase():'CONNECTING'; renderWatch(); renderTabs(); if(!focusInContent()&&!(tab==='catalogue'&&renderedTab==='catalogue'&&renderedCat===catIndex&&renderedCatLen===catalogue.length)) renderContent(); labelButtons() }
  function labelButtons(){ const tips={
    'PAUSE':'Pause the simulation clock; no movement, events, or cooldowns advance.',
    '1X WATCH':'Run the bridge at 1 simulated minute per real minute for deliberate tactical play.',
    '4X TRANSIT':'Run the bridge at 4 simulated minutes per real minute while crossing quiet space.',
    '60X WARP':'Run the bridge at 60 simulated minutes per real minute during uneventful strategic transit; it will stop on important events.',
    'START PATROL':'Start the patrol for the room. You must hold Command or be the room host.',
    'LISTEN PASS':'Spend one passive listening pass to reveal more of the selected contact signature.',
    'SHIP DATABASE':'Open the reference catalogue of ship classes, artwork, and waveform profiles.',
    'KEY RADAR':'Key active radar for precise range and bearing; this broadcasts your position.',
    'STOW RADAR':'Turn off active radar and stop broadcasting your position.',
    'HIGH-POWER PING':'Perform a precise active sweep; it costs battery and increases exposure.',
    'DEEP GRAV SWEEP':'Perform a detailed towed-gravidar scan; the array must have headway.',
    '15 KPS':'Set a slow navigation speed suitable for cautious sensor work.',
    '60 KPS':'Set cruise navigation speed for normal transit.',
    'FLANK':'Set maximum speed; cross space faster but increase noise and detection risk.',
    'CRUISE':'Use normal cruise operations and movement behavior.',
    'QUIET':'Reduce emissions and speed for stealthy operations.',
    'STAND DOWN':'Make all weapons safe and cancel the current firing posture.',
    'COMMAND':'Open the Command station for patrol status, readiness, and decisions.',
    'OPS':'Open Operations for navigation, speed, and the tactical map.',
    'SENSORS':'Open Sensors for passive, active, gravidar, EM, and signature analysis.',
    'COMMS':'Open Communications and Weapons for transmissions and firing posture.',
    'CATALOGUE':'Open the ship database and reference waveform catalogue.',
    'LOG':'Open the chronological bridge log.'
  }; document.querySelectorAll('button').forEach(b=>{if(!b.title){const text=b.textContent.trim();b.title=tips[text]|| (text==='CLAIM'?'Claim this open crew station.':text==='TAG'?'Commit to this catalogue identification; correctness will not be revealed.':text==='OPEN'?'Open this station for crew assignment.':text.startsWith('TIGHT-BEAM')?'Send a low-exposure tight-beam transmission.':text.startsWith('BURST')?'Send a fast but more detectable burst transmission.':text.startsWith('OPEN')?'Broadcast openly to reach distant listeners while revealing your position.':text.startsWith('SPOOF')?'Transmit deceptive traffic; may mislead an enemy but raises suspicion.':text.startsWith('START')?'Start the patrol for all crew in this room.':`Choose or activate: ${text}.`)}}) }
  function renderWatch(){ const hazard=(state.campaign.hazards||[]).find(h=>h.startMinute<=state.clock&&(h.endMinute==null||state.clock<=h.endMinute)); const cooling=Object.entries(state.cooldowns||{}).filter(([,t])=>t>state.clock).map(([a,t])=>`${a} ${Math.ceil(t-state.clock)}m`).join(' · '); const mode=state.timeMode||'paused'; $('watch').innerHTML=`<strong>${esc(state.ship.name)}</strong><span class="muted">${(state.clock/60|0).toString().padStart(2,'0')}:${Math.round(state.clock%60).toString().padStart(2,'0')} SIM</span><button class="${mode==='paused'?'active':''}" onclick="window.mode('paused')">PAUSE</button><button class="${mode==='slow'?'active':''}" onclick="window.mode('slow')">1X WATCH</button><button class="${mode==='fast'?'active':''}" onclick="window.mode('fast')">4X TRANSIT</button><button class="${mode==='warp'?'active':''}" onclick="window.mode('warp')">60X WARP</button><strong>${mode.toUpperCase()} · ${mode==='paused'?'CLOCK STOPPED':mode==='slow'?'1 SIM MIN / REAL MIN':mode==='fast'?'4 SIM MIN / REAL MIN':'60 SIM MIN / REAL MIN'}</strong><span>${hazard?`⚠ ${esc(hazard.title)}`:'CLEAR SPACE'}</span><span>EXP ${Math.round(state.ship.exposure)}% · NOISE ${state.noise.toFixed(2)}</span><span>${esc(String(state.posture||'transit').toUpperCase())}</span><span>FUEL ${(Math.round(state.ship.fuel*10)/10)}/${Math.round(state.ship.fuelCapacity)}</span><span>RNG ${Math.round(state.ship.fuelRangeKlik||0)} KLIK</span><span>${esc(String(state.environment||'clear-space').replace(/-/g,' ').toUpperCase())}${(state.campaign.hazards||[]).filter(h=>h.startMinute>state.clock).length?' · NEXT '+esc(String((state.campaign.hazards||[]).filter(h=>h.startMinute>state.clock)[0].title)):''}</span><span>HEAT ${Math.round(state.ship.heat||0)}%</span><span>FATIGUE ${Math.round(state.ship.fatigue||0)}%</span>${state.ship.shaken?'<span class="danger">SHAKEN</span>':''}${state.jumpState&&state.jumpState.spooling?'<span class="danger">SPOOLING</span>':''}${state.barrierAlert?'<span class="danger">PICKET LINE</span>':''}${state.ship.deadDrift?'<span class="danger">DEAD DRIFT</span>':(state.ship.fuel<=(state.ship.bingoFuel||0)?'<span class="muted">BINGO</span>':'')}${cooling?`<span class="muted">COOLING: ${esc(cooling)}</span>`:''}${state.lastCheck?`<span class="muted" title="last station check">${esc(state.lastCheck.skill)}: d20 ${state.lastCheck.roll} ${state.lastCheck.modifier>=0?'+':''}${state.lastCheck.modifier} vs DC ${state.lastCheck.dc} — ${esc(state.lastCheck.outcome.toUpperCase())}</span>`:''}${(state.status!=='lobby'&&mySession&&Object.values(state.seats).some(x=>x.player&&x.player.sessionId===mySession))?`<button onclick="window.unseat()" title="Leave your station so another crew member can take it">LEAVE SEAT</button>`:''}` }
  function renderTabs(){ $('tabs').innerHTML=['command','ops','sensors','comms','catalogue','log'].map(x=>`<button class="${tab===x?'active':''}" onclick="window.tab('${x}')">${x.toUpperCase()}</button>`).join('') }
  function renderContent(){ renderedTab=tab; renderedCat=catIndex; renderedCatLen=catalogue.length; if(state.status==='lobby')return lobbyView(); if(state.status==='ended'&&tab!=='log'&&tab!=='catalogue')return endedView(); if(tab==='catalogue')return catalogueView(); if(tab==='log')return logView(); if(tab==='comms')return commsView(); if(tab==='command')return commandView(); if(tab==='ops')return opsView(); sensorsView() }
  function careerLine(){const d=state.digest||{};return d.xp!=null?`<p class="muted">CAREER — ${d.xp} XP · STANDING ${d.reputation} · ${(d.medals||[]).length?esc((d.medals||[]).join(', ')):'NO MEDALS'}</p>`:''}
  function canFire(){const seat=Object.values(state.seats||{}).find(x=>x.player&&x.player.sessionId===mySession);return !!seat&&['comms','command'].includes(seat.id);}
  function endedView(){ const last=(state.log||[]).slice().reverse().find(x=>x.source==='COMMAND'); $('content').innerHTML=`<section class="card"><h2>WATCH ENDED</h2><h1 class="${state.outcome==='lost'?'danger':'good'}">${state.outcome?state.outcome.toUpperCase():'COMPLETE'}</h1><p>${esc(state.endReason||last?.text||'The watch has ended.')}</p><p class="muted">SIM TIME ${(state.clock/60|0).toString().padStart(2,'0')}:${Math.round(state.clock%60).toString().padStart(2,'0')} · ${esc(state.campaign.title)}</p>${careerLine()}<button onclick="window.tab('log')">VIEW FULL LOG</button></section>` }
  function seatRow(x){ const mine=!!(x.player&&mySession&&x.player.sessionId===mySession); return `<div class="contact"><strong>${esc(x.title)}</strong><span class="muted">${x.player?`OCCUPIED · ${esc(x.player.name)}${mine?' (YOU)':''}`:'OPEN · '+x.hats.join(' · ').toUpperCase()}</span>${mine?`<button onclick="window.unseat()" title="Leave this station so another crew member can take it">LEAVE SEAT</button>`:!x.player?`<button onclick="window.seat('${x.id}')" title="Take this station">CLAIM</button>`:''}</div>`; }
  function seatPanel(){ return Object.values(state.seats).map(seatRow).join(''); }
  function lobbyView(){ const seated=!!(mySession&&Object.values(state.seats).some(x=>x.player&&x.player.sessionId===mySession)); $('content').innerHTML=`<div class="grid"><section class="card"><h2>${esc(state.campaign.title)}</h2><p>${esc(state.campaign.brief)}</p><p class="muted">OBJECTIVE: ${esc(state.campaign.target)}</p></section><section class="card"><h2>CREW — CLAIM A STATION</h2>${seatPanel()}<p class="muted">${seated?'LEAVE SEAT frees your station for someone else — then CLAIM another to swap.':'Take a station to act.'}</p><button onclick="window.start()">START PATROL</button></section></div>` }
  function navMax(){ const cs=state.contacts.filter(c=>c.everDetected); const wps=state.ship.waypoints||[]; return Math.max(100,...cs.flatMap(c=>[Math.abs(c.pos.x),Math.abs(c.pos.y)]),...wps.flatMap(w=>[Math.abs(w.x),Math.abs(w.y)]),Math.abs(state.ship.pos.x),Math.abs(state.ship.pos.y)); }
  function opsView(){ const contacts=state.contacts.filter(c=>c.everDetected); const wps=state.ship.waypoints||[]; const pts=[...contacts.map(c=>({x:c.pos.x,y:c.pos.y,label:c.name,kind:c.hostile?'hostile':'contact',image:c.image||c.vdu||'',solved:state.ship.weaponsState==='locked'&&state.ship.weaponTarget===c.id})),{x:state.ship.pos.x,y:state.ship.pos.y,label:'OWN SHIP',kind:'own',image:'',solved:false}]; const max=navMax(); const xy=p=>({x:160+p.x/max*145,y:180-p.y/max*145}); const route=[{x:state.ship.pos.x,y:state.ship.pos.y},...wps.map(w=>({x:w.x,y:w.y}))].map(xy); $('content').innerHTML=`<div class="grid"><section class="card"><h2>OPERATIONS / NAVIGATION</h2><svg class="navmap" viewBox="0 0 320 360" onclick="window.plotClick(event)" style="cursor:crosshair"><circle cx="160" cy="180" r="145" fill="none" stroke="#203442"/><circle cx="160" cy="180" r="95" fill="none" stroke="#142733"/><line x1="15" y1="180" x2="305" y2="180" stroke="#142733"/><line x1="160" y1="35" x2="160" y2="325" stroke="#142733"/><text x="152" y="24">N</text>${(state.campaign.barriers||[]).map(bl=>{const p1=xy(bl.a),p2=xy(bl.b);return `<line x1="${p1.x}" y1="${p1.y}" x2="${p2.x}" y2="${p2.y}" stroke="#ff4d4d" stroke-width="2" stroke-dasharray="6 3" opacity=".75"><title>${esc(bl.name)} picket line</title></line>`}).join('')}${state.ship.fuelRangeKlik?`<circle cx="${xy(state.ship.pos).x}" cy="${xy(state.ship.pos).y}" r="${Math.min(160,state.ship.fuelRangeKlik/max*145)}" fill="none" stroke="#ffb545" stroke-dasharray="4 4" opacity=".7"><title>fuel range ${Math.round(state.ship.fuelRangeKlik)} klik</title></circle>`:''}${(state.datums||[]).map(d=>{const q=xy(d.pos);return `<circle cx="${q.x}" cy="${q.y}" r="${Math.max(4,d.radiusKlik/max*145)}" fill="#ff4d4d" opacity=".14" stroke="#ff4d4d" stroke-dasharray="3 3"><title>datum ${Math.round(d.strength*100)}% · ${Math.round(d.ageMinutes)} min</title></circle>`}).join('')}${(state.campaign.hazards||[]).filter(h=>h.startMinute<=state.clock&&(h.endMinute==null||state.clock<=h.endMinute)).map((h,i)=>`<circle cx="${70+i*70}" cy="${70+i*40}" r="28" fill="#ffb545" opacity=".12" stroke="#ffb545" stroke-dasharray="3 3"/><text x="${45+i*70}" y="${70+i*40}">HAZARD</text>`).join('')}${route.length>1?`<polyline points="${route.map(q=>q.x+','+q.y).join(' ')}" fill="none" stroke="#00f0ff" stroke-width="1.5" stroke-dasharray="5 4" opacity=".85"/>`:''}${route.slice(1).map((q,i)=>`<circle cx="${q.x}" cy="${q.y}" r="4" fill="#00f0ff"/><text x="${q.x+6}" y="${q.y+13}" fill="#00f0ff">${i+1}</text>`).join('')}${pts.map(p=>{const q=xy(p);if(p.solved&&p.image)return `<rect x="${q.x-12}" y="${q.y-9}" width="24" height="18" fill="#04090d"/><image href="${esc(p.image)}" x="${q.x-12}" y="${q.y-9}" width="24" height="18" preserveAspectRatio="xMidYMid meet"/><rect x="${q.x-12}" y="${q.y-9}" width="24" height="18" fill="none" stroke="#00f0ff" stroke-width="0.7"/><text x="${q.x+14}" y="${q.y+3}">${esc(p.label)}</text>`;return `<circle cx="${q.x}" cy="${q.y}" r="${p.kind==='own'?6:4}" fill="${p.kind==='own'?'#42d9e7':p.kind==='hostile'?'#ff6b73':'#ffb545'}"/><text x="${q.x+7}" y="${q.y+3}">${esc(p.label)}</text>`}).join('')}<text x="12" y="350">RANGE ±${Math.round(max)} KLIK · CAPSHIPS MOVE SLOWLY</text></svg><p class="muted">COURSE ${Math.round(state.ship.heading)}° · SPEED ${state.ship.speed.toFixed(1)} KPS · POSITION ${state.ship.pos.x.toFixed(0)}, ${state.ship.pos.y.toFixed(0)}</p><p class="muted">CLICK THE PLOT TO SET A WAYPOINT (${wps.length}/6) · OPS OR COMMAND SEAT</p><div class="row"><button onclick="window.speed(15)">3 KPS</button><button onclick="window.speed(60)">8 KPS</button><button onclick="window.speed(100)">FLANK</button><button onclick="window.navmode('cruise')">CRUISE</button><button onclick="window.navmode('quiet')">QUIET</button><button onclick="window.clearWaypoints()" ${wps.length?'':'disabled'}>CLEAR COURSE</button></div></section><section class="card"><h2>JUMP DRIVE</h2><div class="readout">DRIVE ${esc(String(state.ship.drive||'standard').toUpperCase())}</div>${(state.campaign.navPoints||[]).filter(n=>n.kind==='jump').map(n=>`<div class="contact"><div class="row"><strong>${esc(n.name)}</strong><span class="muted">${esc(n.jumpType.toUpperCase())} · NEEDS ${Math.round(n.alignmentRequired*100)}%</span></div><span class="muted">WINDOW ${n.windowOpen}–${n.windowClose==null?'OPEN':n.windowClose} MIN${n.interference?' · INTERFERENCE '+Math.round(n.interference*100)+'%':''}</span><div class="row"><button onclick="window.jumpSpool('${n.id}')" title="Spool the drive — the ship goes blind, slow and loud while alignment builds">SPOOL</button></div></div>`).join('')||'<p class="muted">No jump point charted.</p>'}${state.jumpState?`<div class="readout">${esc(state.jumpState.name)} · ${esc(state.jumpState.outcome.toUpperCase())}<br>ALIGNMENT ${Math.round(state.jumpState.alignment*100)}% / ${Math.round(state.jumpState.required*100)}%${state.jumpState.spooling?' · SPOOLING':''}${state.jumpState.ready?' · READY':''}<br>WINDOW ${state.jumpState.windowOpen?'OPEN':'CLOSED'}</div><div class="bar ${state.jumpState.ready?'':'amber'}"><i style="width:${Math.round(state.jumpState.alignment*100)}%"></i></div>${state.jumpState.spooling?`<div class="row"><button onclick="window.jumpCommit()">COMMIT</button><button onclick="window.jumpAbort()">ABORT</button></div>`:''}`:''}<p class="muted">Committing below the required alignment is a misjump; below the floor the drive will not engage. Interference raises the requirement.</p></section><section class="card"><h2>THE HUNT</h2><div class="readout">LAYER ${esc(state.layer||'surface')}${state.layerCrossUntil&&state.clock<state.layerCrossUntil?' · CROSSING':''}</div>${contacts.length?`<div class="row">${contacts.slice(0,3).map(x=>`<button onclick="window.tma('${x.id}')" title="Fly a deliberate course change to solve this bearing-only track">TMA ${esc(x.name)}</button>`).join('')}</div>`:''}${state.tma?`<span class="muted">TMA LEG ON ${esc(state.tma.contactId)} · RATE ${state.tma.bearingRate}°/LEG</span>`:''}<div class="row"><button onclick="window.posture('transit')" class="${state.posture==='transit'?'active':''}">TRANSIT</button><button onclick="window.posture('sprint')" class="${state.posture==='sprint'?'active':''}" title="Fast and loud — detection climbs">SPRINT</button><button onclick="window.posture('drift')" class="${state.posture==='drift'?'active':''}" title="Slow and silent — detection and datums decay">DRIFT</button></div>${(state.datums||[]).length?state.datums.map(d=>`<div class="contact"><div class="row"><strong>DATUM</strong><span class="muted">${Math.round(d.strength*100)}% · AGE ${Math.round(d.ageMinutes)} MIN</span></div><div class="bar red"><i style="width:${Math.round(d.strength*100)}%"></i></div><span class="muted">SEARCH RADIUS ${Math.round(d.radiusKlik)} KLIK · ${esc(d.source)}</span></div>`).join(''):'<p class="muted">No active datum — no hunter has a fix.</p>'}</section><section class="card"><h2>ASTROMETRICS</h2>${`<div class="readout">NAV ERROR ±${Math.round(state.ship.navErrorKlik||0)} KLIK · ${esc(state.commsNote||'')}</div><div class="row"><button onclick="window.navFix('star')" title="Star sighting — a clean sky gives a good fix">STAR FIX</button><button onclick="window.navFix('landmark')" title="Fix off a charted nav point within 30 klik">LANDMARK</button><button onclick="window.navFix('ping')" title="Radar fix — exact, but it shouts your position">PING FIX</button></div>`}${(state.plotLegs||[]).map(l=>`<div class="contact ${state.navTarget===l.navId?'focus':''}"><div class="row"><strong>${esc(l.name)}</strong><span class="muted">${esc(l.kind.toUpperCase())}${l.chartAgeHours>=16?' · STALE CHART':''}</span></div><span class="muted">${Math.round(l.timeMinutes)} MIN · ${l.fuelCost} FUEL · EXP ${l.exposure}${l.uncertaintyMinutes?' · ±'+Math.round(l.uncertaintyMinutes)+' MIN':''} · ${esc(l.risk.toUpperCase())}</span><div class="row"><button onclick="window.plotLeg('${l.navId}')">PLOT</button><button onclick="window.commitLeg('${l.navId}')" title="Commit the leg — an Astrogation Check sets arrival precision">COMMIT</button><button onclick="window.surveyNav('${l.navId}')" title="Sensors re-survey this chart, lowering the Astrogation DC">SURVEY</button></div></div>`).join('')||'<p class="muted">No charted points.</p>'}${state.navCommit?`<div class="readout">UNDER WAY TO ${esc(state.navCommit.name)}<br>ASTROGATION ${esc(state.navCommit.outcome.toUpperCase())}${state.navCommit.offsetKlik>0?'<br>ARRIVAL '+state.navCommit.offsetKlik+' KLIK OFF-AXIS':'<br>ON-AXIS ARRIVAL'}${state.navCommit.staleCharts?'<br>CHARTS WERE STALE':''}</div>`:''}<p class="muted">Time, fuel and exposure per leg. Stale charts raise the Astrogation DC and the arrival error; sensors can re-survey.</p></section><section class="card"><h2>ENVIRONMENT</h2>${(state.campaign.hazards||[]).map(h=>`<div class="contact"><strong>${esc(h.title)}</strong><span class="muted">${h.startMinute}–${h.endMinute??'END'} MIN · INTENSITY ${Math.round(h.intensity*100)}%</span></div>`).join('')||'No known hazards.'}</section></div>` }
function commandView(){ const hostiles=state.contacts.filter(c=>c.hostile); const tracked=hostiles.filter(c=>c.everDetected&&c.state!=='unknown').length; const inside=hostiles.filter(c=>Math.hypot(c.pos.x-state.ship.pos.x,c.pos.y-state.ship.pos.y)<=120).length; const darkHours=Math.max(0,Math.floor((state.clock-(state.campaign.startHour||0)*60)/60)); $('content').innerHTML=`<div class="grid"><section class="card"><h2>COMMAND</h2><p>${esc(state.campaign.title)} · ${esc(state.campaign.theater)}</p><p>${esc(state.campaign.brief)}</p><div class="bar"><i style="width:${state.ship.readiness}%"></i></div><span class="muted">READINESS ${Math.round(state.ship.readiness)}%</span><p class="muted">PATROL OBJECTIVE — TRACK EVERY HOSTILE (${tracked}/${hostiles.length}) · OUTLAST THE LANE (${inside} INSIDE 120 KLIK) · STAY DARK ${darkHours}H/6H</p></section><section class="card"><h2>DECISION EVENTS</h2>${state.events?.length?state.events.map(e=>`<div class="contact"><strong>${esc(e.title)}</strong><p>${esc(e.text)}</p>${e.options.map(o=>`<button onclick="window.resolve('${e.id}','${o.id}')">${esc(o.label)}</button>`).join(' ')}</div>`).join(''):'No pending decisions.'}</section><section class="card"><h2>ALERT &amp; DEFENCES</h2><div class="row">${["three","two","one"].map(l=>`<button class="${state.ship.alert===l?'active':''}" onclick="window.setAlert('${l}')" title="Condition Three is peacetime; Two raises shields; One arms the mounts and costs a fuel point">${l==='three'?'THREE':l==='two'?'TWO · SHIELDS':'ONE · ACTION'}</button>`).join('')}</div><div class="readout">FUEL ${Math.round(state.ship.fuel)}/${Math.round(state.ship.fuelCapacity)} · CORE ${Math.round(state.ship.core)}%</div>${Object.entries(state.ship.shields||{}).map(([arc,v])=>{const r=v.max?v.shp/v.max:0;return `<div class="bar ${r<0.34?'red':r<0.67?'amber':''}"><i style="width:${Math.round(r*100)}%"></i></div><span class="muted">${arc.toUpperCase()} ${Math.round(v.shp)}/${Math.round(v.max)} SHP</span>`}).join('')}</section><section class="card"><h2>DAMAGE CONTROL</h2>${Object.entries(state.ship.systems||{}).map(([n,h])=>{const cls=h.malfunctioning?'red':h.health<60?'amber':'';return `<div class="contact"><div class="row"><strong>${esc(n)}</strong><span class="muted">${h.malfunctioning?'DOWN':'OK'}</span></div><div class="bar ${cls}"><i style="width:${Math.round(h.health)}%"></i></div><span class="muted">HEALTH ${Math.round(h.health)}% · WEAR ${Math.round(h.wear)}%${h.juryRigged?' · RIGGED':''}</span><div class="row"><button onclick="window.repair('${n}',false)">REPAIR</button><button onclick="window.repair('${n}',true)">JURY-RIG</button><button onclick="window.maintain('${n}')">SERVICE</button></div></div>`}).join('')}<p class="muted">Repairs take time and a Check; a jury-rig works now and fails again under fire. Armour and core cannot be repaired underway.</p></section><section class="card"><h2>SHIPYARD</h2><div class="readout">HULL ${esc(state.ship.class||'')} · ${esc(state.ship.shipClass||'')}<br>POWER ${(state.ship.modules||[]).length}· MASS · CARGO ${Math.round(state.ship.cargoCapacity||0)}</div>${(state.ship.hardpoints||[]).map(hp=>`<span class="muted">${esc(hp.id)} · ${esc(String(hp.arc).toUpperCase())} · ${esc(hp.fitted||'EMPTY')}</span>`).join('<br>')}<div class="row">${(state.moduleCatalog||[]).map(m=>`<button onclick="window.fitModule('${m}')" class="${(state.ship.modules||[]).includes(m)?'active':''}" title="Fit ${esc(m)} if power, mass and cargo allow">${esc(String(m).toUpperCase())}</button>`).join('')}</div>${(state.ship.modules||[]).length?`<div class="row">${state.ship.modules.map(m=>`<button onclick="window.unfitModule('${m}')">STRIP ${esc(String(m).toUpperCase())}</button>`).join('')}</div>`:''}<p class="muted">Hardpoints are arc-coded: a fore gun cannot bear on a contact astern. Modules cost power, mass and cargo, and a fitted module can be hit.</p></section><section class="card"><h2>ENDURANCE</h2><div class="readout">HEAT ${Math.round(state.ship.heat||0)}% · ${esc(String(state.ship.heatMode||'normal').toUpperCase())}<br>FATIGUE ${Math.round(state.ship.fatigue||0)}% · ${esc(String(state.ship.watchBill||'standard').toUpperCase())}${state.ship.shaken?' · <span class="danger">SHAKEN</span>':''}<br>CREW ${Math.round(state.ship.crewStrength||100)}%</div><div class="bar ${(state.ship.heat||0)>=70?'red':(state.ship.heat||0)>=40?'amber':''}"><i style="width:${Math.round(state.ship.heat||0)}%"></i></div><div class="row">${["normal","vent","bottle"].map(m=>`<button onclick="window.heatMode('${m}')" class="${state.ship.heatMode===m?'active':''}" title="Venting dumps heat fast and loudly; bottling is quiet but the heat stays">${m.toUpperCase()}</button>`).join('')}</div><div class="readout">SPARES ${state.ship.spares||0} · PROVISIONS ${Math.round(state.ship.provisions||0)}H · ${esc(String(state.environment||'clear-space').replace(/-/g,' ').toUpperCase())}</div><div class="row"><button onclick="window.salvage()" title="Go outside in a debris field for spares — EVA risks exposure and injury">SALVAGE</button><button onclick="window.replenish()" title="Take on fuel, spares and provisions at a depot">REPLENISH</button></div><div class="row">${["standard","battle","rest"].map(b=>`<button onclick="window.watchBill('${b}')" class="${state.ship.watchBill===b?'active':''}">${b.toUpperCase()}</button>`).join('')}${state.ship.shaken?`<button onclick="window.rally()">RALLY</button>`:''}</div><p class="muted">Heat is capability, not exposure: run hot and every station works worse. Fatigue builds on watch; rest recovers it but thins the watch.</p></section><section class="card"><h2>CREW STATIONS</h2>${seatPanel()}<p class="muted">LEAVE SEAT frees your station; then CLAIM another to swap.</p></section></div>` }
  function gravScope(all,sel){ const R=100,cx=120,cy=120,RANGE=50;
    const P=(r,b)=>{const a=(b-90)*Math.PI/180;return [cx+r*Math.cos(a),cy+r*Math.sin(a)];};
    const arc=(r,b0,b1)=>{const p0=P(r,b0),p1=P(r,b1);const span=((b1-b0)%360+360)%360;const large=span>180?1:0;return `M ${p0[0].toFixed(1)} ${p0[1].toFixed(1)} A ${r.toFixed(1)} ${r.toFixed(1)} 0 ${large} 1 ${p1[0].toFixed(1)} ${p1[1].toFixed(1)}`;};
    const arcs=(all||[]).filter(c=>c.sensor&&c.sensor.gravArc&&c.sensor.gravRange!=null).map(c=>{const a=c.sensor.gravArc,rr=Math.max(8,Math.min(R,c.sensor.gravRange/RANGE*R)),mass=Math.max(a.massKt||1,1),heat=Math.min(1,mass/80);return {b:((a.bearing%360)+360)%360,hw:Math.max(2,a.halfWidth||2),rr,mass,w:Math.max(3,Math.min(16,3+Math.log10(mass)*4)),color:heat>0.55?'#ff6b73':heat>0.2?'#ffb545':'#42d9e7',sel:!!(sel&&c.id===sel.id)};});
    return `<svg class="gravscope" viewBox="0 0 240 240"><circle cx="${cx}" cy="${cy}" r="${R}" fill="#04090d" stroke="#203442"/><circle cx="${cx}" cy="${cy}" r="66" fill="none" stroke="#142733"/><circle cx="${cx}" cy="${cy}" r="33" fill="none" stroke="#142733"/><line x1="${cx-R}" y1="${cy}" x2="${cx+R}" y2="${cy}" stroke="#142733"/><line x1="${cx}" y1="${cy-R}" x2="${cx}" y2="${cy+R}" stroke="#142733"/><text x="${cx}" y="11" text-anchor="middle" fill="#7890a0" font-size="9">N</text><text x="${cx+6}" y="${cy+14}" fill="#40536a" font-size="8">${Math.round(RANGE/3)}</text><text x="${cx+6}" y="${cy-Math.round(2*R/3)+13}" fill="#40536a" font-size="8">${Math.round(2*RANGE/3)}</text>${arcs.map(a=>`<path d="${arc(a.rr,a.b-a.hw,a.b+a.hw)}" fill="none" stroke="${a.color}" stroke-width="${a.w.toFixed(1)}" stroke-linecap="round" opacity="${a.sel?0.95:0.55}"/>`).join('')}<circle cx="${cx}" cy="${cy}" r="3" fill="#42d9e7"/><text x="6" y="236" fill="#7890a0" font-size="8">MASS ARCS · RANGE ${RANGE} KLIK</text></svg>`;}
  function sensorsView(){ const seen=state.contacts.filter(c=>c.everDetected); const c=seen.find(x=>x.id===focus)||seen[0]; const active=state.ship.activeSensor; const moving=state.ship.speed>0.01; const em=seen.filter(x=>x.radiusKlik===0); const gravs=state.contacts.filter(x=>x.sensor&&x.sensor.gravArc); $('content').innerHTML=`<div class="grid"><section class="card sensor-card"><h2>PASSIVE SIGNATURE ANALYZER</h2>${c?contactView(c):'<p>Listening for contacts...</p>'}</section><section class="card sensor-card"><h2>ACTIVE RADAR</h2><div class="readout">STATUS ${active?'KEYED':'STOWED'}<br>RANGE ${c?.sensor?.activeRange==null?'—':Math.round(c.sensor.activeRange)+' KLIK'}<br>BEARING ${c?.sensor?.activeBearing==null?'—':Math.round(c.sensor.activeBearing)+'°'}</div><div class="row"><button onclick="window.active(${!active})">${active?'STOW':'KEY'} RADAR</button><button ${active?'':'disabled'} onclick="window.sweep()">HIGH-POWER PING</button></div><p class="muted">Precise range and bearing; broadcasts your position.</p></section><section class="card sensor-card"><h2>TOWED GRAVIDAR</h2>${gravScope(state.contacts,c)}<div class="readout">ARRAY ${moving?'STREAMED':'STOWED'}<br>${c?.sensor?.gravRange!=null?'RANGE '+Math.round(c.sensor.gravRange)+' ± '+Math.round(c.sensor.gravRangeError)+' KLIK':(gravs.length?gravs.length+' MASS RETURN'+(gravs.length===1?'':'S')+' ON SCOPE':'NO MASS RETURN')}</div><button ${moving?'':'disabled'} onclick="window.grav()">DEEP GRAV SWEEP</button><p class="muted">Mass arcs and approximate distance. Requires headway.</p></section><section class="card sensor-card"><h2>EM / MOTION</h2>${em.length?em.map(x=>`<div class="readout">${esc(x.name)} · ${x.sensor?.emCourse==null?'NO VECTOR':`CSE ${Math.round(x.sensor.emCourse)}° · SPD ${Math.round(x.sensor.emSpeed||0)} KPS · Q ${Math.round((x.sensor.emQuality||0)*100)}%`}</div>`).join(''):'<p class="muted">No moving contacts.</p>'}<p class="muted">Passive drive-plume course and speed; hazards and glare can scramble it.</p></section><section class="card"><h2>INTERCEPT CLOCK</h2>${c&&c.sensor&&c.sensor.cpaKlik!=null?`<div class="readout">${esc(c.name)}<br>ETA ${c.sensor.etaMinutes==null?'—':Math.round(c.sensor.etaMinutes)+' MIN'} TO 40 KLIK<br>CPA ${c.sensor.cpaKlik} KLIK IN ${Math.round(c.sensor.cpaMinutes)} MIN${c.sensor.tmaRangeKlik!=null?`<br>TMA RANGE ~${c.sensor.tmaRangeKlik} KLIK (Q${Math.round(c.sensor.tmaQuality*100)}%)`:""}</div>`:'<p class="muted">No intercept solution on the focused track.</p>'}${seen.filter(x=>x.sensor&&x.sensor.etaMinutes!=null).map(x=>`<div class="contact" onclick="window.focus('${x.id}')"><strong>${esc(x.name)}</strong><span class="muted">ETA ${Math.round(x.sensor.etaMinutes)} MIN · CPA ${x.sensor.cpaKlik} KLIK</span></div>`).join('')}</section><section class="card"><h2>DATUM &amp; BAFFLES</h2>${(state.datums||[]).length?state.datums.map(d=>`<div class="contact"><div class="row"><strong>DATUM</strong><span class="muted">${Math.round(d.strength*100)}% · ${Math.round(d.radiusKlik)} KLIK</span></div><span class="muted">AGE ${Math.round(d.ageMinutes)} MIN · ${esc(d.source)}</span></div>`).join(''):'<p class="muted">No datum on the plot.</p>'}<div class="row"><button onclick="window.clearBaffles()" title="A hard turn aft — clears the blind arc, but the turn is heard">CLEAR BAFFLES</button></div><p class="muted">The towed array is blind astern; clearing costs time and noise.</p></section><section class="card"><h2>INBOUND</h2>${(state.ordnance||[]).length?state.ordnance.map(o=>`<div class="contact"><div class="row"><strong>${esc(o.name)}</strong><span class="muted">${o.detected?'TRACKED':'NO LOCK'} · FUEL ${Math.round(o.fuelKlik)}</span></div><span class="muted">WARHEAD ${o.warhead} · ${esc(String(o.kind).toUpperCase())}</span><div class="row"><button onclick="window.shootOrdnance('${o.id}')" title="A gun solution on the inbound weapon">SHOOT IT DOWN</button></div></div>`).join(''):'<p class="muted">Nothing inbound.</p>'}<div class="row"><button onclick="window.spoof()" title="Fire a spoofing pod — a shot that beat the EHD may still miss">SPOOF (${state.ship.spoofPods||0})</button></div><p class="muted">A weapon in the water can be tracked, shot down, decoyed, or lost in terrain.</p></section><section class="card"><h2>CONTACT BOARD</h2>${seen.map(x=>{const solved=state.ship.weaponsState==='locked'&&state.ship.weaponTarget===x.id;return `<div class="contact ${c&&x.id===c.id?'focus':''}" onclick="window.focus('${x.id}')">${solved?`<img class="board-thumb" src="${esc(x.image||x.vdu||'/img/brief/unknown.png')}" onerror="this.src='/img/brief/unknown.png'">`:''}<strong>${esc(x.name)}</strong><span class="muted">${x.state.toUpperCase()} · ${Math.round(x.confidence*100)}% · TAG ${x.guess==='unknown'?'NONE':esc(x.guess.toUpperCase())}</span></div>`}).join('')||'No contacts detected.'}</section></div>` }
  function contactView(c){const bands=c.sensor?.bands||[]; const matches=c.sensor?.catalogueMatches||[]; const solved=state.ship.weaponsState==='locked'&&state.ship.weaponTarget===c.id; const pic=c.image||c.vdu||'/img/brief/unknown.png'; const wpn=prepWeapon||state.ship.weapon||'laser-cannon'; const sht=prepShot||state.ship.shotType||'quick'; const mounts=[['laser-cannon','LASER CANNON'],['mass-driver','MASS DRIVER'],['particle-cannon','PARTICLE CANNON'],['heat-seeker','HEAT SEEKER'],['image-recognition-missile','IMAGING MISSILE'],['torpedo','TORPEDO']]; return `<div class="contact-head"><img class="contact-thumb${solved?'':' unknown'}" src="${esc(solved?pic:'/img/brief/unknown.png')}" onerror="this.src='/img/brief/unknown.png'"><div><p><strong>${esc(c.name)}</strong> · waveform ${Math.round((c.waveform?.progress||0)*100)}%</p><span class="muted">${solved?'SOLUTION LOCKED — HULL RESOLVED':'NO FIRING SOLUTION — HULL UNKNOWN'}</span></div></div>${plot(bands)}<p class="muted">PARTIAL PLOT — COMPARE AGAINST CATALOGUE; VERIFICATION UNAVAILABLE</p><div>${matches.length?`<p class="muted">SHIP TYPES — best match first</p>`+matches.map(m=>`<div class="candidate"><span title="${esc(m.name||m.shipClass)}">${esc(m.name||m.shipClass)}</span><span class="muted">${esc(m.contactType)} · ${Math.round(m.score*100)}% <button onclick="window.tag('${c.id}','${m.contactType}')">TAG</button></span></div>`).join(''):'<p class="muted">No catalogue candidates — listen longer, or this return is terrain.</p>'}</div><div class="row"><button onclick="window.listen('${c.id}')">LISTEN PASS</button><button onclick="window.openCatalogue()">SHIP DATABASE</button></div><div class="row" style="margin-top:8px${canFire()?'':';display:none'}"><select onchange="window.setPrepWeapon(this.value)">${mounts.map(m=>`<option value="${m[0]}" ${wpn===m[0]?'selected':''}>${m[1]}</option>`).join('')}</select><select onchange="window.setPrepShot(this.value)"><option value="quick" ${sht==='quick'?'selected':''}>QUICK SHOT</option><option value="refined" ${sht==='refined'?'selected':''}>REFINED SHOT</option></select><button onclick="window.prep('${c.id}','armed')">PREP SOLUTION</button><button onclick="window.prep('${c.id}','locked')">LOCK SOLUTION</button></div>`}
  function plot(bands){const n=bands.length||16;return `<svg class="plot" viewBox="0 0 320 150" preserveAspectRatio="none">${Array.from({length:n},(_,i)=>{const v=bands[i]||0;return `<rect x="${i*(320/n)}" y="${140-v*125}" width="${320/n*.8}" height="${Math.max(2,v*125)}" opacity="${.3+v*.7}"/>`}).join('')}<line x1="250" x2="250" y1="0" y2="140" stroke="#ffb545" stroke-dasharray="3 3"/><text x="5" y="147" fill="#7890a0" font-size="9">FREQUENCY BANDS · 21cm REF</text></svg>`}
  function commsView(){ const seen=state.contacts.filter(c=>c.everDetected); $('content').innerHTML=`<div class="grid"><section class="card"><h2>COMMUNICATIONS WATCH</h2><div class="row"><button onclick="window.intercept()">INTERCEPT THE NETS</button><span class="muted">listen before you speak</span></div>${seen.length?seen.map(c=>`<div class="contact"><div class="row"><strong>${esc(c.name)}</strong><span class="muted">${c.guess==='unknown'?'UNKNOWN':esc(c.guess.toUpperCase())}</span></div><span class="muted">IFF ${Math.round((c.iffConfidence||0)*100)}%${c.spoofDetected?' · <span class="danger">SPOOF DETECTED</span>':''}</span><button onclick="window.iff('${c.id}')" title="Send an IFF challenge — a legitimate vessel answers; a hostile may lie or go comms-dark">CHALLENGE IFF</button></div>`).join(''):'<p class="muted">No detectable traffic to challenge.</p>'}</section><section class="card"><h2>EVASIVE &amp; FIRE CONTROL</h2><div class="row">${["jink","slip-90","slip-180","snap-turn","break"].map(m=>`<button onclick="window.maneuver('${m}')" title="A defensive manoeuvre makes us harder to hit and spoils our own aim; a new helm order drops it">${m.toUpperCase()}</button>`).join('')}</div><div class="row">${["radar","comms","engines","guns","ordnance","shields"].map(sys=>`<button onclick="window.targetSystem('${sys}')" class="${state.ship.weaponTargetSystem===sys?'active':''}" title="Aim the shot at a named system — a Targeting Check decides whether it lands there">${sys.toUpperCase()}</button>`).join('')}<button onclick="window.targetSystem('')">HULL</button></div><div class="readout">TARGET ${esc(state.ship.weaponTargetSystem?String(state.ship.weaponTargetSystem).toUpperCase():'HULL')}<br>MANEUVER ${esc(state.ship.maneuver||'STEADY')}<br>EVASIVE +${state.ship.maneuverEvasive||0} · OUR GUNNERY -${state.ship.maneuverGunnery||0}</div>${state.ship.weaponEhd?`<div class="readout">EHD ${state.ship.weaponEhd.ehd} = HD ${state.ship.weaponEhd.targetHd} + EVA ${state.ship.weaponEhd.evasive} + RNG ${state.ship.weaponEhd.rangePenalty} − TAC ${state.ship.weaponEhd.tactical} − SOL ${state.ship.weaponEhd.solutionBonus}</div>`:'<p class="muted">Prep a solution to see the shot\'s EHD.</p>'}<p class="muted">Higher EHD is harder to hit. Manoeuvring is two-sided: it defends you and spoils your shot.</p></section><section class="card"><h2>TRANSMISSION</h2><p>Weapons: <strong>${state.ship.weaponsState||state.ship.roe}</strong> · RoE <strong>${state.ship.roe.toUpperCase()}</strong></p><div class="readout">${esc(state.commsNote||'relay window —')}</div><div class="row">${['tight-beam','burst','open','spoof'].map(m=>`<button onclick="window.transmit('${m}')">${m.toUpperCase()}</button>`).join('')}<button onclick="window.standdown()">STAND DOWN</button></div><p class="muted">Transmission modes trade exposure for reach. Weapons preparation is performed from a tagged contact.</p></section></div>` }
  function catalogueView(){ if(!catalogue.length){$('content').innerHTML=`<section class="card"><h2>SHIP DATABASE / SIGNATURE REFERENCE</h2><p class="muted">No catalogue loaded.</p></section>`;return;} const i=Math.max(0,Math.min(catIndex,catalogue.length-1)); const x=catalogue[i]; $('content').innerHTML=`<section class="card"><h2>SHIP DATABASE / SIGNATURE REFERENCE</h2><p class="muted">Reference profiles are not contact truth. Compare the live plot in SENSORS, then commit your tag.</p><article class="catalogue-entry carousel"><img src="${esc(x.image||x.vdu||'/img/brief/unknown.png')}" onerror="this.src='/img/brief/unknown.png'"><div><strong>${esc(x.name)}</strong><div class="muted">${esc(x.role)} · ${esc(x.contactType)}</div><p>${esc(x.blurb)}</p>${plot(x.bands||[]).replace('class="plot"','class="plot" style="height:80px"')}</div></article><div class="carousel-nav"><button onclick="window.catStep(-1)" ${i<=0?'disabled':''}>&#9664; PREV</button><span class="muted">${i+1} / ${catalogue.length}</span><button onclick="window.catStep(1)" ${i>=catalogue.length-1?'disabled':''}>NEXT &#9654;</button></div></section>` }
  function logView(){ $('content').innerHTML=`<section class="card"><h2>BRIDGE LOG</h2>${(state.log||[]).slice().reverse().map(x=>`<p><span class="muted">${x.time.toFixed(1)} · ${esc(x.source)}</span> ${esc(x.text)}</p>`).join('')}</section>` }
  window.tab=x=>{tab=x;render()}; window.focus=x=>{focus=x;render()}; window.openCatalogue=()=>{tab='catalogue';render()}; window.catStep=d=>{catIndex=Math.max(0,Math.min(catalogue.length-1,catIndex+d));render()}; window.unseat=()=>send({type:'setSeat',seat:null}); window.prep=(id,st)=>send({type:'weapons:prep',contactId:id,state:st,weapon:prepWeapon||state.ship.weapon||'laser-cannon',shot:prepShot||state.ship.shotType||'quick'}); window.setPrepWeapon=v=>{prepWeapon=v}; window.setPrepShot=v=>{prepShot=v}; window.mode=x=>send({type:'setTimeMode',mode:x}); window.listen=x=>send({type:'sensor:listen',contactId:x}); window.tag=(x,g)=>send({type:'sensor:claim',contactId:x,guess:g}); window.resolve=(e,o)=>send({type:'resolveEvent',eventId:e,optionId:o}); window.transmit=x=>send({type:'comms:transmit',mode:x}); window.iff=x=>send({type:'comms:iff',contactId:x}); window.setAlert=l=>send({type:'setAlert',level:l}); window.repair=(s,rig)=>send({type:'dc:repair',system:s,juryRig:!!rig}); window.maintain=s=>send({type:'dc:maintain',system:s}); window.plotLeg=id=>send({type:'nav:plot',navId:id}); window.commitLeg=id=>send({type:'nav:commit',navId:id}); window.surveyNav=id=>send({type:'nav:survey',navId:id}); window.jumpSpool=id=>send({type:'jump:spool',navId:id}); window.jumpCommit=()=>send({type:'jump:commit'}); window.jumpAbort=()=>send({type:'jump:abort'}); window.navFix=m=>send({type:'nav:fix',method:m}); window.posture=p=>send({type:'ops:posture',posture:p}); window.clearBaffles=()=>send({type:'sensor:clearBaffles'}); window.tma=id=>send({type:'ops:tma',contactId:id}); window.maneuver=m=>send({type:'ops:maneuver',maneuver:m}); window.targetSystem=s=>send({type:'weapons:targetSystem',system:s}); window.shootOrdnance=id=>send({type:'sensor:shootOrdnance',ordnanceId:id}); window.spoof=()=>send({type:'sensor:spoof'}); window.heatMode=m=>send({type:'ops:heat',mode:m}); window.watchBill=b=>send({type:'ops:watch',bill:b}); window.rally=()=>send({type:'ops:rally'}); window.salvage=()=>send({type:'dc:salvage'}); window.replenish=()=>send({type:'nav:replenish'}); window.fitModule=m=>send({type:'dc:fitModule',moduleId:m}); window.unfitModule=m=>send({type:'dc:unfitModule',moduleId:m}); window.intercept=()=>send({type:'comms:intercept'}); window.standdown=()=>send({type:'weapons:standdown'}); window.seat=x=>send({type:'setSeat',seat:x}); window.start=()=>send({type:'start'}); window.speed=x=>send({type:'nav:speed',kps:x}); window.navmode=x=>send({type:'nav:mode',mode:x}); window.active=x=>send({type:'sensor:active',on:x}); window.sweep=()=>send({type:'sensor:activeSweep'}); window.waypoint=(x,y)=>{const wps=(state.ship.waypoints||[]).map(w=>({x:w.x,y:w.y,z:w.z||0}));wps.push({x,y,z:0});send({type:'nav:waypoints',waypoints:wps.slice(-6)})}; window.clearWaypoints=()=>send({type:'nav:waypoints',waypoints:[]}); window.plotClick=evt=>{const svg=evt.currentTarget,m=svg.getScreenCTM();if(!m)return;const pt=svg.createSVGPoint();pt.x=evt.clientX;pt.y=evt.clientY;const loc=pt.matrixTransform(m.inverse()),mx=navMax();window.waypoint(Math.round((loc.x-160)/145*mx),Math.round((180-loc.y)/145*mx))}; window.grav=()=>send({type:'sensor:gravScan'}); connect();
})();
